"""Temporal conditions, generated by a typed, weighted grammar.

`TGen` writes conditions that are safe and well typed by construction (each variable is bound by
`exists` or a `for` list and restricted by a positive atom before any filter reads it), unless a
near miss is requested: `misses` names the near-miss kinds the generator may apply, at the first
choice points where each fits, and `applied` records the ones it did.
"""

from __future__ import annotations

from model import (DEC_POOL, LONG, LONG_POOL, STR_POOL, STRING, BOOL, Ty, base_of, ent, is_ident,
                   leaves, literal_text, lookup, ns_of, q)
from eventschema import seconds

# Cedar's extension types other than `decimal`, which temporal conditions do not support.
UNSUPPORTED_EXTS = ("datetime", "duration", "ipaddr")


def holds_unsupported(t: Ty) -> bool:
    """Whether `t` is, or holds as a set element or record attribute, an unsupported type."""
    if t.kind in UNSUPPORTED_EXTS:
        return True
    if t.kind == "Set" and t.elem is not None:
        return holds_unsupported(t.elem)
    if t.kind == "Record":
        return any(holds_unsupported(a) for (_, a, _) in t.attrs)
    return False

WINDOWS = ["1s", "30s", "1m", "5m", "10m", "1h", "2h", "90m", "24h", "1d", "3600s", "12h"]


def path_text(p) -> str:
    return ".".join(p)


def nameable(p) -> bool:
    return all(is_ident(s) for s in p)


class TGen:
    # The conjuncts, aggregates and variable types where each near miss can be applied.
    MISS_SITES = {
        "operand_string_order": ("exists", None, "String"), "operand_type_mismatch": ("exists", None, "Long"),
        "operand_entity_types": ("exists", None, "Entity"), "operand_bool_order": ("exists", None, "Bool"),
        "operand_decimal_order": ("exists", None, "decimal"), "tp_ordered": ("two_tp", None, None),
        "tp_eq_long": ("two_tp", None, None), "array_in_arith": ("arith", None, None),
        "summand_string": ("sum", "sum", None), "binder_dup": ("count", "count_val", None),
        "wildcard_operand": ("count", None, None), "compound_agg_event": ("count", "count_tp", None),
        "timedep_agg_const": ("count", "count_tp", None), "tp_long": ("count", "count_tp", None),
        "existential_unrestricted": ("exists", None, None), "binder_type_undeclared": ("exists", None, "Entity"),
        "binder_type_unqualified": ("exists", None, "Entity"),
    }

    def __init__(self, g, w, events, es, rule, misses=(), miss_rate=0.5, macros=None):
        self.g = g
        self.w = w
        self.events = [e for e in events]
        self.es = es
        self.rule = rule  # policy.RuleShape: actions, ptypes, rtypes
        self.max_w = es.window_seconds()
        self.misses = set(misses)
        self.miss_rate = miss_rate
        self.applied = []
        self.counter = 0
        self.windows = []
        self.macros = macros or {}  # name -> macro descriptor available to call
        self.ctx_paths = rule.context_paths()
        self.p_attrs = rule.principal_attrs(w)
        self.r_attrs = rule.resource_attrs(w)

    # ─── near misses ───────────────────────────────────────────────────

    def miss(self, kind: str) -> bool:
        if kind in self.misses and kind not in self.applied and self.g.r.random() < self.miss_rate:
            self.applied.append(kind)
            self.g.tag(f"miss:{kind}")
            return True
        return False

    def fresh(self, base="v") -> str:
        self.counter += 1
        if self.g.p(0.03, "temporal:binder_named_like_pin"):
            return self.g.choice(["__pin_ti0", "__pin_", "__pin_tj1", "__pin_x"]) + (
                str(self.counter) if self.g.p(0.5) else "")
        return f"{base}{self.counter}"

    # ─── windows ───────────────────────────────────────────────────────

    def window(self) -> str:
        if self.miss("window_over"):
            s = self.max_w + self.g.choice([1, 60, 3600])
            w = f"{s}s"
        elif self.miss("window_zero"):
            w = "0s"
        elif self.g.p(0.06, "temporal:window_at_cap"):
            w = f"{self.max_w}s" if self.g.p(0.5) else self.cap_text()
        else:
            ok = [x for x in WINDOWS if seconds(x) <= self.max_w]
            w = self.g.choice(ok or ["1s"])
        self.windows.append(seconds(w) if w[:-1].isdigit() else 0)
        return w

    def cap_text(self) -> str:
        return self.es.max_window or "24h"

    # ─── events and predicates ─────────────────────────────────────────

    def pick_event(self, need=None):
        """An event, with a leaf of type `need` if given (and one exists)."""
        evs = self.events
        if need is not None:
            evs = [e for e in evs if self.leaves_of(e, need)]
        if not evs:
            return None
        # Prefer events of the rule's own actions and of history kinds a little.
        return self.g.choice(evs)

    def leaves_of(self, e, need: Ty):
        out = []
        for l in e.leaves:
            if not nameable(l.path):
                continue
            t = l.single()
            if t is not None and t == need:
                out.append(l)
        return out

    def kind_text(self, e) -> str:
        if self.miss("kind_undeclared"):
            return self.g.choice(["reqest", "responce", "nope"])
        return e.kind

    def action_text(self, e) -> str:
        if self.miss("action_undeclared"):
            return f"{ns_action(e.action.ns)}::{q('Nope')}"
        return e.action.uid

    def pred(self, e, bind=None, correlate=None, n_extra=None) -> str:
        """A predicate on event `e`. `bind`: `(var, type)` the predicate restricts; `correlate`:
        restricted variables `{var: type}` it may read."""
        correlate = correlate or {}
        args = []
        used = set()
        if bind is not None:
            var, ty = bind
            if ty.kind == "Timepoint":
                pass
            else:
                cands = self.leaves_of(e, ty)
                if cands:
                    l = self.g.choice(cands)
                    args.append((path_text(l.path), var))
                    used.add(l.path)
        nl = [l for l in e.leaves if nameable(l.path) and l.path not in used]
        k = n_extra if n_extra is not None else self.g.choice([0, 0, 1, 1, 1, 2, 3])
        for l in self.g.sample(nl, k):
            t = self.arg_term(l, correlate)
            if t is not None:
                args.append((path_text(l.path), t))
        if self.miss("field_undeclared"):
            args.append((self.g.choice(["input.nosuch", "nosuch", "output.zz"]), "*"))
        if self.miss("field_group"):
            gl = [l for l in e.leaves if len(l.path) > 1 and nameable(l.path)]
            if gl:
                args.append((gl[0].path[0], "*"))
        if self.miss("named_arg_type"):
            nl2 = [l for l in e.leaves if l.origin == "named" and l.single() == STRING and nameable(l.path)]
            if nl2:
                args.append((path_text(nl2[0].path), "5"))
        if self.g.p(0.03, "temporal:duplicate_arg") and args:
            args.append(args[0])
        self.g.r.shuffle(args) if self.g.p(0.2) else None
        body = ", ".join(f"{p}: {t}" for (p, t) in args)
        head = f"{self.action_text(e)}::{self.kind_text(e)}"
        if self.g.p(0.04, "temporal:refinement") and args:
            # Refinement outside a macro: `P{a}{b}`, which expansion merges.
            a1, a2 = args[: len(args) // 2], args[len(args) // 2:]
            return head + "{" + ", ".join(f"{p}: {t}" for (p, t) in a1) + "}{" + ", ".join(
                f"{p}: {t}" for (p, t) in a2) + "}"
        return head + "{" + (" " + body + " " if body else "") + "}"

    def arg_term(self, l, correlate):
        """A term for a predicate argument on leaf `l`."""
        t = l.single()
        opts = [("wild", 3)]
        if t is not None and literal_text(self.g.r, t, self.w) is not None:
            opts.append(("lit", 4))
        # Temporal conditions do not support `datetime`, `duration`, and `ipaddr`: such a field is
        # matched by a wildcard only.
        supported = t is not None and not holds_unsupported(t)
        cps = [p for (p, ct, req) in self.ctx_paths if supported and ct == t and req]
        if cps:
            opts.append(("ctx", 6))
        if self.principal_fits(l):
            opts.append(("principal", 5))
        if self.resource_fits(l):
            opts.append(("resource", 3))
        pas = [n for (n, at, req) in self.p_attrs if supported and at == t and req]
        if pas:
            opts.append(("pattr", 2))
        cvs = [v for (v, vt) in correlate.items() if t is not None and vt == t]
        if cvs:
            opts.append(("var", 6))
        if self.miss("arg_type"):
            return self.wrong_literal(t)
        if self.miss("arg_principal_wrong") and not self.principal_fits(l):
            return "principal"
        if self.miss("ctx_path_undeclared"):
            return "context.input.nosuch"
        if self.miss("ctx_path_optional"):
            ops = [p for (p, ct, req) in self.ctx_paths if t is not None and ct == t and not req]
            if ops:
                return "context." + path_text(ops[0])
        if self.miss("principal_attr_undeclared"):
            return "principal.nosuch"
        if self.miss("entity_undeclared_type") and t is not None and t.kind == "Entity":
            ns = ns_of(t.name)
            return (f"{ns}::" if ns else "") + f"Nope::{q('x')}"
        if self.miss("enum_bad_eid") and t is not None and t.kind == "Entity" and self.w.entity(t.name) \
                and self.w.entity(t.name).enum is not None:
            return f"{t.name}::{q('nope')}"
        if self.miss("decimal_bad") and t is not None and t.kind == "decimal":
            return self.g.choice(['decimal("1.23456")', 'decimal("abc")', 'decimal("1")'])
        if self.miss("array_arg"):
            return "[" + ", ".join(q(s) for s in self.g.sample(STR_POOL, 2)) + "]"
        if self.miss("wildcard_underscore"):
            return "_"
        kind = self.g.weighted(opts)
        if kind == "wild":
            return self.g.choice(["*", "_"])
        if kind == "lit":
            return literal_text(self.g.r, t, self.w)
        if kind == "ctx":
            return "context." + path_text(self.g.choice(cps))
        if kind == "principal":
            if self.g.p(0.1, "temporal:principal_uid_literal"):
                return f"{self.g.choice(self.rule.ptypes)}::{q(self.g.choice(self.w.ids_of(self.rule.ptypes[0])))}"
            return "principal"
        if kind == "resource":
            return "resource"
        if kind == "pattr":
            self.g.tag("temporal:principal_attr_arg")
            return "principal." + self.g.choice(pas)
        if kind == "var":
            return self.g.choice(cvs)
        return "*"

    def principal_fits(self, l) -> bool:
        return bool(self.rule.ptypes) and all(l.admits_entity(p) for p in self.rule.ptypes)

    def resource_fits(self, l) -> bool:
        return bool(self.rule.rtypes) and all(l.admits_entity(p) for p in self.rule.rtypes)

    def wrong_literal(self, t):
        if t == STRING:
            return self.g.choice(["5", "true", 'decimal("1.0")'])
        if t == LONG:
            return self.g.choice([q("five"), "true"])
        if t is not None and t.kind == "Entity":
            return self.g.choice([q("alice"), "1"])
        return q("x")

    # ─── types of variables ────────────────────────────────────────────

    def var_types(self):
        """Types of leaves a variable can be bound to, from the derived events."""
        seen = []
        for e in self.events:
            for l in e.leaves:
                t = l.single()
                if t is not None and nameable(l.path) and t.kind in ("String", "Long", "Bool", "Entity",
                                                                       "decimal") and t not in seen:
                    seen.append(t)
        return seen

    def type_text(self, t: Ty) -> str:
        if t.kind == "Timepoint":
            return "Timepoint"
        if t.kind == "Entity":
            if self.miss("binder_type_unqualified") and "::" in t.name:
                return base_of(t.name)
            return t.name
        return t.kind

    def binder_type_text(self, t: Ty) -> str:
        if self.miss("binder_type_undeclared"):
            return (ns_of(t.name) + "::Nope") if t.kind == "Entity" and ns_of(t.name) else "Nope"
        return self.type_text(t)

    # ─── conditions ────────────────────────────────────────────────────

    def leaf(self, depth=2) -> str:
        """A temporal leaf: a closed, time-dependent condition."""
        n = self.g.choice([1, 1, 1, 2, 2, 3])
        parts = []
        for i in range(n):
            parts.append(self.conjunct(depth, {}, last=(i == n - 1)))
        if self.miss("timedep_const"):
            cps = [p for (p, ct, req) in self.ctx_paths if ct == LONG and req]
            parts.append(f"context.{path_text(cps[0])} > 1" if cps else "1 == 1")
        return " && ".join(parts)

    def conjunct(self, depth, env, last=True) -> str:
        """A closed (given `env`), time-dependent conjunct."""
        opts = [("formerly", 10), ("previous", 3), ("since", 4), ("exists", 7), ("count", 5),
                ("count_bind", 3), ("sum", 2), ("neg", 3), ("pred", 2), ("arith", 1),
                ("macro", 3), ("distinct", 1), ("formerly_chain", 3), ("same_tp", 1),
                ("two_tp", 1), ("count_two_dom", 1), ("since_in_formerly", 1), ("previous_chain", 1)]
        if depth <= 0:
            opts = [("formerly", 5), ("pred", 2), ("previous", 1), ("neg", 1)]
        for m in self.misses:
            site = self.MISS_SITES.get(m)
            if site and m not in self.applied:
                opts = [(k, w * (8 if k == site[0] else 1)) for (k, w) in opts]
        k = self.g.weighted(opts)
        self.g.tag(f"temporal:{k}")
        s = getattr(self, "c_" + k)(depth, env)
        # A conjunct that ends in an unparenthesized aggregate, an `exists`, or a `since` would
        # swallow the conjuncts after it: fence it unless it is the last.
        if not last and not (s.startswith("(") and s.endswith(")") and balanced(s[1:-1])):
            s = f"({s})"
        return s

    def atom(self, depth, env, bind=None) -> str:
        """The body of a temporal operator: a predicate, or a parenthesized chain."""
        e = self.pick_event(bind[1] if bind and bind[1].kind != "Timepoint" else None) or self.pick_event()
        if e is None:
            return "tp(x)"
        if depth > 0 and self.g.p(0.3):
            first = self.pred(e, bind=bind, correlate=env)
            rest = self.filter_on(depth - 1, env)
            return f"({first} && {rest})"
        return self.pred(e, bind=bind, correlate=env)

    def filter_on(self, depth, env) -> str:
        """A conjunct that follows a restricting one in a body: a guarded negation, a
        comparison of restricted variables, another predicate, or a nested operator."""
        k = self.g.weighted([("neg_pred", 4), ("pred", 3), ("cmp", 3 if env else 0),
                             ("previous", 1), ("ctx_cmp", 1)])
        self.g.tag(f"temporal:filter_{k}")
        if k == "neg_pred":
            e = self.pick_event()
            return "!" + self.pred(e, correlate=env)
        if k == "pred":
            return self.pred(self.pick_event(), correlate=env)
        if k == "cmp" and env:
            return self.var_cmp(env)
        if k == "previous":
            return f"previous within {self.window()} {self.pred(self.pick_event(), correlate=env)}"
        cps = [p for (p, ct, req) in self.ctx_paths if ct == LONG and req]
        if cps:
            return f"context.{path_text(self.g.choice(cps))} {self.g.choice(['<', '>=', '==', '!='])} {self.g.choice(LONG_POOL)}"
        return "!" + self.pred(self.pick_event(), correlate=env)

    def var_cmp(self, env) -> str:
        v, t = self.g.choice(list(env.items()))
        if self.miss("tp_ordered") and t.kind == "Timepoint":
            others = [x for (x, y) in env.items() if y.kind == "Timepoint" and x != v]
            if others:
                return f"{v} < {others[0]}"
        if t.kind == "Timepoint":
            if self.miss("tp_eq_long"):
                return f"{v} == 5"
            others = [x for (x, y) in env.items() if y.kind == "Timepoint" and x != v]
            if others:
                return f"{v} {self.g.choice(['==', '!='])} {others[0]}"
            return f"{v} == {v}"
        if t == LONG:
            if self.miss("operand_type_mismatch"):
                return f"{v} == {q('s')}"
            rhs = self.g.choice([str(self.g.choice(LONG_POOL)), str(self.g.choice(LONG_POOL)),
                                 *[f"context.{path_text(p)}" for (p, ct, req) in self.ctx_paths if ct == LONG and req]])
            if self.g.p(0.15, "temporal:arith_filter"):
                return f"{v} + {self.g.choice([1, 2, 10])} {self.g.choice(['<', '<=', '>', '>='])} {rhs}"
            return f"{v} {self.g.choice(['<', '<=', '>', '>=', '==', '!='])} {rhs}"
        if t == STRING:
            if self.miss("operand_string_order"):
                return f"{v} < {q('m')}"
            cps = [f"context.{path_text(p)}" for (p, ct, req) in self.ctx_paths if ct == STRING and req]
            rhs = self.g.choice([q(self.g.choice(STR_POOL))] + cps)
            return f"{v} {self.g.choice(['==', '!='])} {rhs}"
        if t.kind == "Entity":
            if self.miss("operand_entity_types"):
                return f"{v} == resource"
            if t.name in self.rule.ptypes and len(self.rule.ptypes) == 1 and self.g.p(0.6):
                return f"{v} {self.g.choice(['==', '!='])} principal"
            return f"{v} != {t.name}::{q(self.g.choice(self.w.ids_of(t.name)))}"
        if t == BOOL:
            if self.miss("operand_bool_order"):
                return f"{v} < true"
            return f"{v} == {self.g.choice(['true', 'false'])}"
        if t.kind == "decimal":
            if self.miss("operand_decimal_order"):
                return f'{v} < decimal("1.0")'
            return f'{v} == decimal("{self.g.choice(DEC_POOL)}")'
        return f"{v} == {v}"

    # Conjunct kinds. Each returns a closed condition given `env` (restricted variables).

    def c_formerly(self, depth, env):
        return f"formerly within {self.window()} {self.atom(depth - 1, env)}"

    def c_previous(self, depth, env):
        return f"previous within {self.window()} {self.atom(depth - 1, env)}"

    def c_pred(self, depth, env):
        return self.pred(self.pick_event(), correlate=env)

    def c_neg(self, depth, env):
        inner = self.g.choice([f"formerly within {self.window()} {self.atom(depth - 1, env)}",
                               self.pred(self.pick_event(), correlate=env)])
        if self.g.p(0.1, "temporal:double_negation"):
            return "!!" + inner
        return "!" + inner

    def c_formerly_chain(self, depth, env):
        e = self.pick_event()
        inner = self.pred(e, correlate=env)
        k = self.g.choice(["neg", "prev", "pred"])
        if k == "neg":
            rest = "!" + self.pred(self.pick_event(), correlate=env)
        elif k == "prev":
            rest = f"previous within {self.window()} {self.pred(self.pick_event(), correlate=env)}"
        else:
            rest = self.pred(self.pick_event(), correlate=env)
        return f"formerly within {self.window()} ({inner} && {rest})"

    def c_since(self, depth, env):
        left_e, right_e = self.pick_event(), self.pick_event()
        w = self.window()
        if self.g.p(0.6, "temporal:since_negated_left"):
            left = "!" + self.pred(left_e, correlate=env)
        elif self.g.p(0.2, "temporal:since_compound_left"):
            left = f"(!{self.pred(left_e, correlate=env)} && !{self.pred(self.pick_event(), correlate=env)})"
        else:
            left = self.pred(left_e, correlate=env)
        right = self.atom(depth - 1, env)
        return f"{left} since within {w} {right}"

    def c_exists(self, depth, env):
        ts = self.var_types()
        if not ts:
            return self.c_formerly(depth, env)
        t = self.g.choice(ts)
        for m in self.misses:
            site = self.MISS_SITES.get(m)
            if site and site[2] and m not in self.applied:
                want = [x for x in ts if x.kind == site[2]]
                if want:
                    t = self.g.choice(want)
        x = self.fresh({"String": "u", "Long": "a", "Entity": "p", "Bool": "b", "decimal": "d"}.get(t.kind, "v"))
        if env and self.g.p(0.05, "temporal:binder_shadow"):
            x = self.g.choice(list(env))
        tt = self.binder_type_text(t)
        e = self.pick_event(t)
        w = self.window()
        how = self.g.weighted([("formerly", 6), ("pred", 1), ("previous", 1), ("since_anchor", 1)])
        self.g.tag(f"temporal:exists_by_{how}")
        env2 = {k: v for (k, v) in env.items() if k != x}
        env2[x] = t
        if how == "formerly":
            first = f"formerly within {w} {self.pred(e, bind=(x, t), correlate=env)}"
        elif how == "previous":
            first = f"previous within {w} {self.pred(e, bind=(x, t), correlate=env)}"
        elif how == "since_anchor":
            first = f"(!{self.pred(self.pick_event(t) or e, correlate=env2)} since within {w} {self.pred(e, bind=(x, t), correlate=env)})"
        else:
            first = self.pred(e, bind=(x, t), correlate=env)
        rest = []
        for _ in range(self.g.choice([0, 1, 1, 2])):
            k = self.g.weighted([("cmp", 4), ("corr", 4), ("neg", 3), ("nested", 1 if depth > 1 else 0)])
            if k == "cmp":
                rest.append(self.var_cmp({x: t}) if self.g.p(0.7) else self.var_cmp(env2))
            elif k == "corr":
                e2 = self.pick_event(t)
                if e2 is not None:
                    rest.append(f"formerly within {self.window()} {self.pred(e2, correlate=env2)}")
            elif k == "neg":
                e2 = self.pick_event(t) or self.pick_event()
                rest.append(f"!formerly within {self.window()} {self.pred(e2, correlate=env2)}")
            else:
                rest.append("(" + self.c_exists(depth - 1, env2) + ")")
        if self.miss("existential_unrestricted"):
            # The restricting atom under a negation: not range-restricted.
            first = "!" + first
        body = " && ".join([first] + rest)
        paren = len(rest) > 0 or self.g.p(0.5)
        return f"exists ({x}: {tt}). " + (f"({body})" if paren else body)

    def agg(self, depth, env, kind=None) -> str:
        """An aggregate: a count or a sum, over timepoints or values."""
        if kind is None:
            for m in self.misses:
                site = self.MISS_SITES.get(m)
                if site and site[1] and m not in self.applied:
                    kind = site[1]
        kind = kind or self.g.weighted([("count_tp", 5), ("count_val", 2), ("sum", 2), ("count_corr", 1)])
        self.g.tag(f"temporal:agg_{kind}")
        w = self.window()
        if kind == "sum":
            e = self.pick_event(LONG)
            if e is None:
                kind = "count_tp"
            else:
                a, t = self.fresh("a"), self.fresh("t")
                if self.miss("summand_string"):
                    es = self.pick_event(STRING)
                    if es is not None:
                        return (f"sum {a} for ({a}: String), ({t}: Timepoint). where (formerly within {w} "
                                f"({self.pred(es, bind=(a, STRING), correlate=env)} && tp({t})))")
                tp_dom = self.g.p(0.7)
                inner = self.pred(e, bind=(a, LONG), correlate=env)
                if tp_dom:
                    return (f"sum {a} for ({a}: Long), ({t}: Timepoint). where (formerly within {w} "
                            f"({inner} && tp({t})))")
                return f"sum {a} for ({a}: Long). where formerly within {w} {inner}"
        if kind == "count_val":
            ts = [t for t in self.var_types() if t.kind in ("String", "Long", "Entity")]
            if ts:
                t = self.g.choice(ts)
                e = self.pick_event(t)
                v = self.fresh("k")
                if self.miss("binder_dup"):
                    return (f"count for ({v}: {self.type_text(t)}), ({v}: {self.type_text(t)}). where "
                            f"formerly within {w} {self.pred(e, bind=(v, t), correlate=env)}")
                return f"count for ({v}: {self.binder_type_text(t)}). where formerly within {w} {self.pred(e, bind=(v, t), correlate=env)}"
        t = self.fresh("t")
        if self.miss("tp_long"):
            return f"count for ({t}: Long). where (formerly within {w} ({self.pred(self.pick_event(), correlate=env)} && tp({t})))"
        if self.miss("compound_agg_event"):
            return (f"count for ({t}: Timepoint). where (formerly within {w} "
                    f"({ns_action(self.w.home)}::{q('Nope')}::request{{}} && tp({t})))")
        if self.miss("timedep_agg_const"):
            x = self.fresh("c")
            return f"count for ({x}: Long). where {x} == 5"
        body = self.pred(self.pick_event(), correlate=env)
        if self.g.p(0.15, "temporal:agg_body_chain"):
            body = f"{body} && !{self.pred(self.pick_event(), correlate=env)}"
        if self.g.p(0.15, "temporal:agg_previous"):
            return f"count for ({t}: Timepoint). where (previous within {w} ({body} && tp({t})))"
        if self.g.p(0.15, "temporal:agg_no_temporal"):
            return f"count for ({t}: Timepoint). where ({body} && tp({t}))"
        return f"count for ({t}: Timepoint). where (formerly within {w} ({body} && tp({t})))"

    def c_count(self, depth, env):
        a = self.agg(depth, env)
        op = self.g.choice(["<", "<=", ">", ">=", "==", "!="])
        k = self.g.choice(LONG_POOL[:6])
        if self.miss("wildcard_operand"):
            return f"({a}) == *"
        if self.g.p(0.5):
            return f"({a}) {op} {k}"
        self.g.tag("temporal:agg_final_position")
        return f"{k} {op} {a}"

    def c_count_bind(self, depth, env):
        a = self.agg(depth, env)
        n = self.fresh("n")
        tail = f"{n} {self.g.choice(['>', '>=', '<', '==', '!='])} {self.g.choice(LONG_POOL[:6])}"
        if self.g.p(0.2, "temporal:bind_reversed"):
            return f"exists ({n}: Long). ({n} == ({a}) && {tail})"
        return f"exists ({n}: Long). (({a}) == {n} && {tail})"

    def c_sum(self, depth, env):
        a = self.agg(depth, env, "sum")
        n = self.fresh("total")
        if self.g.p(0.5):
            return f"({a}) {self.g.choice(['<', '<=', '>', '>='])} {self.g.choice(LONG_POOL)}"
        return f"exists ({n}: Long). (({a}) == {n} && {n} > {self.g.choice(LONG_POOL)})"

    def c_arith(self, depth, env):
        self.g.tag("temporal:arithmetic")
        a1, a2 = self.agg(depth, env), self.agg(depth, env)
        cps = [f"context.{path_text(p)}" for (p, ct, req) in self.ctx_paths if ct == LONG and req]
        k = self.g.choice(["diff", "plus_ctx", "scaled", "nested"])
        if self.miss("array_in_arith"):
            return f"({a1}) * 2 >= [1, 2]"
        if k == "diff":
            return f"({a1}) - ({a2}) <= {self.g.choice([0, 1, 2, 5])}"
        if k == "plus_ctx" and cps:
            return f"({a1}) + {self.g.choice(cps)} <= {self.g.choice(LONG_POOL)}"
        if k == "scaled":
            return f"100 * ({a1}) <= 85 * {a2}"
        return f"(({a1}) + 1) * 2 > {self.g.choice([0, 3, 10])}"

    def c_distinct(self, depth, env):
        if "count_distinct_within" not in self.macros:
            return self.c_count(depth, env)
        e = self.pick_event(STRING)
        if e is None:
            return self.c_count(depth, env)
        u, d = self.fresh("u"), self.fresh("d")
        return (f"exists ({d}: Long). (count_distinct_within({u}, {self.window()}, "
                f"{self.pred(e, bind=(u, STRING), correlate=env)}) == {d} && {d} > {self.g.choice([0, 1, 2])})")

    def c_same_tp(self, depth, env):
        """Two predicates at one timepoint: both hold of the same event."""
        t = self.fresh("t")
        e1, e2 = self.pick_event(), self.pick_event()
        return (f"exists ({t}: Timepoint). (formerly within {self.window()} ({self.pred(e1, correlate=env)} && tp({t})) "
                f"&& formerly within {self.window()} ({self.pred(e2, correlate=env)} && tp({t})))")

    def c_two_tp(self, depth, env):
        """Two timepoints, ordered apart or equal, compared only by equality."""
        s, t = self.fresh("s"), self.fresh("t")
        e1, e2 = self.pick_event(), self.pick_event()
        tp = Ty("Timepoint")
        cmp = self.var_cmp({s: tp, t: tp})
        return (f"exists ({s}: Timepoint). exists ({t}: Timepoint). (formerly within {self.window()} "
                f"({self.pred(e1, correlate=env)} && tp({s})) && formerly within {self.window()} "
                f"({self.pred(e2, correlate=env)} && tp({t})) && {cmp})")

    def c_count_two_dom(self, depth, env):
        """A count over a value and a timepoint."""
        e = self.pick_event(STRING)
        if e is None:
            return self.c_count(depth, env)
        u, t = self.fresh("u"), self.fresh("t")
        a = (f"count for ({u}: String), ({t}: Timepoint). where (formerly within {self.window()} "
             f"({self.pred(e, bind=(u, STRING), correlate=env)} && tp({t})))")
        return f"({a}) {self.g.choice(['>=', '<', '==', '!='])} {self.g.choice([0, 1, 2, 3])}"

    def c_since_in_formerly(self, depth, env):
        left = "!" + self.pred(self.pick_event(), correlate=env)
        right = self.pred(self.pick_event(), correlate=env)
        return f"formerly within {self.window()} ({left} since within {self.window()} {right})"

    def c_previous_chain(self, depth, env):
        inner = f"previous within {self.window()} {self.pred(self.pick_event(), correlate=env)}"
        return f"previous within {self.window()} ({self.pred(self.pick_event(), correlate=env)} && {inner})"

    def c_macro(self, depth, env):
        """A call of a macro the bundle defines or inherits."""
        names = [n for n in self.macros if self.macros[n].callable]
        if not names:
            return self.c_formerly(depth, env)
        m = self.macros[self.g.choice(names)]
        self.g.tag(f"macro:call:{m.shape}")
        return m.call(self, depth, env)


def balanced(s: str) -> bool:
    """`s` has balanced parentheses outside string literals, never closing below depth 0."""
    d, in_str, esc = 0, False, False
    for c in s:
        if in_str:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
            continue
        if c == '"':
            in_str = True
        elif c == "(":
            d += 1
        elif c == ")":
            d -= 1
            if d < 0:
                return False
    return d == 0


def ns_action(ns: str) -> str:
    return f"{ns}::Action" if ns else "Action"
